# owner: platform
"""Tests for snapping spans to a step and labelling them."""

import unittest

from hourglass.rounding import round_span_labels
from hourglass.rounding import round_to_step
from hourglass.models import Span

class RoundToStepTests(unittest.TestCase):
    def test_rounds_down_below_half_step(self):
        self.assertEqual(round_to_step(7, 15), 0)

    def test_rounds_up_above_half_step(self):
        self.assertEqual(round_to_step(8, 15), 15)

    def test_exact_half_rounds_up(self):
        self.assertEqual(round_to_step(15, 30), 30)

    def test_multiple_of_step_is_unchanged(self):
        self.assertEqual(round_to_step(120, 15), 120)

class RoundSpanLabelsTests(unittest.TestCase):
    def test_labels_rounded_span(self):
        spans = [Span(538, 1032)]
        self.assertEqual(
            round_span_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_end_at_midnight_is_allowed(self):
        spans = [Span(1380, 1440)]
        self.assertEqual(
            round_span_labels(spans, 15),
            ["23:00-24:00 (1h 0m)"]
        )

    def test_keeps_order_of_spans(self):
        spans = [Span(600, 720), Span(540, 600)]
        self.assertEqual(
            round_span_labels(spans, 60),
            ["10:00-12:00 (2h 0m)", "09:00-10:00 (1h 0m)"]
        )

    def test_empty_list_gives_empty_list(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_span_that_rounds_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(1, 3)], 15)

    def test_zero_step_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(540, 600)], 0)

    def test_negative_step_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(540, 600)], -15)

    def test_step_not_dividing_an_hour_raises(self):
        with self.assertRaises(ValueError):
            round_span_labels([Span(540, 600)], 25)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            round_span_labels([], 7)
